class Solution:
    def maximumValue(self, strs: list[str]) -> int:
        def get_val(s):
            return int(s) if s.isdigit() else len(s)
        return max(get_val(s) for s in strs)

class Solution {
public:
    int maximumValue(std::vector<std::string>& strs) {
        int max_val = 0;
        for (const auto& s : strs) {
            bool all_digits = true;
            for (char c : s) {
                if (!std::isdigit(c)) {
                    all_digits = false;
                    break;
                }
            }
            int val = all_digits ? std::stoi(s) : s.length();
            if (val > max_val) max_val = val;
        }
        return max_val;
    }
};

class Solution {
    public int maximumValue(String[] strs) {
        int maxVal = 0;
        for (String s : strs) {
            boolean allDigits = true;
            for (int i = 0; i < s.length(); i++) {
                if (!Character.isDigit(s.charAt(i))) {
                    allDigits = false;
                    break;
                }
            }
            int val = allDigits ? Integer.parseInt(s) : s.length();
            if (val > maxVal) maxVal = val;
        }
        return maxVal;
    }
}

var maximumValue = function(strs) {
    let maxVal = 0;
    for (const s of strs) {
        const isAllDigits = /^\d+$/.test(s);
        const val = isAllDigits ? Number(s) : s.length;
        if (val > maxVal) maxVal = val;
    }
    return maxVal;
};
